  "cloud.credSets.title": "Další sady přihlašovacích údajů",
  "cloud.credSets.hint": "Dejte jednomu nebo více vzdáleným cílům vlastní přihlašovací údaje S3 nebo restic REST místo sdílení výše uvedených.",
