  "recovery.encUnknown": "Zatím to nelze určit: repozitáře se nepodařilo otevřít, takže jejich režim šifrování je neznámý. Oprav umístění výše a zkontroluj to znovu, nebo ho nastav sám, pokud ho už znáš.",
  "recovery.encConflict": "Tvoje repozitáře si odporují: některé jsou zašifrované, jiné ne. Jedno nastavení nemůže otevřít obojí. Nasměruj ten vybočující na nové prázdné místo, nebo obnovuj jen z odpovídající sady.",
  "recovery.encUnconfigured": "Zatím není nastavené žádné umístění záloh. Vyplň cesty níže a pak se připoj.",
  "recovery.encDetectHint": "Šifrování není otázka preference: repozitář vznikne buď s heslem (odvozeným z tvého APP_KEY), nebo bez něj, a to už se nikdy nezmění. BombVault nastavené repozitáře otevře, aby zjistil, který případ nastal, takže obnova na čerstvém stroji nevyžaduje hádání. Nedosažitelný repozitář se hlásí jako neznámý, nikdy jako nešifrovaný.",
