  "dbdump.saveHint": "Zapíše výpis jako soubor do zvolené složky na serveru, s vlastníkem nobody:users, abys ho mohl otevřít přes síťové sdílení. Soubor obsahuje všechny tabulky i hashe hesel databázových uživatelů; ulož ho tam, kam se dostaneš jen ty.",
  "dbdump.saveCancelHint": "Zrušení ukládání zastaví a nedokončený soubor odstraní.",
  "dbdump.savedTo": "Uloženo do {path}",
  "dbdump.import": "Importovat do čisté databáze",
  "dbdump.importConfirm": "Importovat tento výpis {engine} {version} do {container}? BombVault kontejner zastaví, jeho datovou složku odsune stranou (zůstává zachovaná, nic se nemaže), spustí kontejner s prázdnou datovou složkou a výpis naimportuje. Aplikace, které tuto databázi používají, uvidí její stav z doby pořízení výpisu.",
  "dbdump.importConfirmNoVersion": "Importovat tento výpis {engine} do {container}? BombVault kontejner zastaví, jeho datovou složku odsune stranou (zůstává zachovaná, nic se nemaže), spustí kontejner s prázdnou datovou složkou a výpis naimportuje. Aplikace, které tuto databázi používají, uvidí její stav z doby pořízení výpisu.",
  "dbdump.importNoVersion": "Tento výpis neuvádí verzi své databáze. Import selže, pokud ho server nedokáže přečíst.",
  "dbdump.importStops": "one=Během importu BombVault zastaví i {apps} a potom ji zase spustí. Když import selže poté, co už začal, stará data zůstanou odložená a aplikace zastavená.|few=Během importu BombVault zastaví i tyto aplikace: {apps}. Potom je zase spustí. Když import selže poté, co už začal, stará data zůstanou odložená a aplikace zastavené.|many=Během importu BombVault zastaví i tyto aplikace: {apps}. Potom je zase spustí. Když import selže poté, co už začal, stará data zůstanou odložená a aplikace zastavené.|other=Během importu BombVault zastaví i tyto aplikace: {apps}. Potom je zase spustí. Když import selže poté, co už začal, stará data zůstanou odložená a aplikace zastavené.",
  "dbdump.importDone": "Databáze naimportována.",
  "dbdump.importRefused.busy": "Právě běží jiná záloha nebo obnova. Zkus to znovu, až doběhne.",
  "dbdump.importRefused.notRunning": "Nejprve spusť kontejner; import potřebuje běžící server.",
  "dbdump.importRefused.engineMismatch": "Tento výpis pochází z jiného typu databáze, než jaký kontejner provozuje.",
  "dbdump.importRefused.noDataMount": "BombVault na datovou složku tohoto kontejneru nedosáhne a nemůže ji bezpečně odsunout. Importuj výpis ručně, jak to popisuje havarijní balíček.",
  "dbdump.importRefused.version": "Server běží ve verzi {server}, výpis pochází z {dump}. Pro tento import použij image s verzí {dump} nebo novější.",
  "dbdump.importRefused.versionSameMajor": "Server běží ve verzi {server}, výpis pochází z {dump}. MySQL a MariaDB importují výpis jen do hlavní verze, ze které pochází, proto pro tento import použij image s verzí {dump}.",
  "dbdump.importRefused.damaged": "Tento výpis je poškozený a nelze ho importovat.",
  "dbdump.importRefused.notADump": "Tento snímek není výpisem databáze tohoto kontejneru.",
  "dbdump.restoreLiveWarn": "Soubory této databáze se kopírují za běhu serveru, takže obnovené soubory nemusí nastartovat čistě. Pokud ne, naimportuj výpis pořízený s touto zálohou, je v seznamu níže.",
  "dbdump.restoreNoneWarn": "Datová složka této databáze v záloze není. Obnovení vrátí kontejner s prázdnou databází; poté naimportuj výpis ze seznamu níže.",
  "dbdump.deleteConfirm": "Smazat tento výpis databáze? Bude odstraněn z repozitáře (místo uvolníš spuštěním Prune v Nastavení). Tohle nelze vzít zpět.",
