  "settings.compression": "Komprese",
  "settings.compressionInfo": "Jak restic ukládá nová data do tohoto repozitáře. Automaticky je výchozí volba restic a hodí se pro většinu dat. Maximum ušetří víc místa a stojí víc času CPU při zálohách a kopiích. Vypnuto ukládá data nekomprimovaná, což pomáhá u dat, která už komprimovaná jsou, třeba videa nebo fotek. Repozitář ve starém formátu verze 1 komprimovat neumí a nastavení ignoruje.",
