  "offsite.rcloneWarning": "rclone serve restic --append-only má otevřenou upstream chybu s opakováním, která může zahodit zápisy (appends). Pro neměnné úložiště mimo lokalitu se doporučuje rest-server.",
  "offsite.s3Unverified": "Poznámka: append-only u S3 nelze ověřit automaticky. Nastavte verzování bucketu + zákaz mazání ručně; scorecard tuto doménu nadále označuje jako neověřenou.",
