  "mcp.stepOAuth": "Zapnout přihlášení",
  "mcp.setupChatGPT": "V ChatGPT otevři Nastavení, Aplikace a konektory a v Pokročilém nastavení zapni vývojářský režim. Pak zvol Vytvořit, pojmenuj konektor, vlož URL konektoru jako URL MCP serveru, zvol OAuth jako ověřování, potvrď, že mu důvěřuješ, a vytvoř ho.",
  "mcp.setupClaudeAi": "Na claude.ai otevři Nastavení, Konektory a zvol Přidat vlastní konektor. Pojmenuj ho, vlož URL konektoru, ID klienta a tajný klíč OAuth nech prázdné a přidej ho. Pak zvol Připojit.",
  "mcp.copyConnector": "Kopírovat URL konektoru",
  "mcp.oauthProxyNote": "Služba volá /mcp, /oauth/ a /.well-known/ ze svých vlastních serverů, takže reverzní proxy s vlastním přihlášením musí tyto cesty pustit až k BombVault.",
  "mcp.oauthWaitTitle": "Čeká se na přihlášení",
