  "mcp.notePerplexity": "Zatím se k MCP serverům na tvém počítači nebo v tvé síti připojuje jen aplikace Perplexity pro Mac; aplikace pro Windows a web ne.",
  "mcp.noteGrok": "Dokumentace Groku neukazuje jeho formulář pro konektory podrobně. Pokud nabízí jen přihlášení a žádné pole pro hlavičku, zatím klíč BombVault použít nemůže.",
  "mcp.certNotForThisAddress": "Certifikát BombVaultu neuvádí {host}, takže asistenti připojení na tuto adresu odmítnou. Přidej adresu do certifikátu a pak si ho stáhni pro úryvky.",
  "mcp.certOwnNotForThisAddress": "Tvůj certifikát neuvádí {host}, takže asistenti připojení na tuto adresu odmítnou. Připoj se přes jméno, které certifikát pokrývá.",
